#!/usr/bin/env bash
set -e
if [ ! -f package.json ]; then echo "ERROR: run this from inside the project/ folder (where package.json is)"; exit 1; fi

mkdir -p "$(dirname "src/types.ts")"
echo "" | base64 -d > "src/types.ts"
echo "wrote src/types.ts"

mkdir -p "$(dirname "src/App.tsx")"
echo "" | base64 -d > "src/App.tsx"
echo "wrote src/App.tsx"

mkdir -p "$(dirname "src/utils/lookups.ts")"
echo "" | base64 -d > "src/utils/lookups.ts"
echo "wrote src/utils/lookups.ts"

mkdir -p "$(dirname "supabase/migrations/20260809120000_add_project_boq_codes_and_boq_headers.sql")"
echo "" | base64 -d > "supabase/migrations/20260809120000_add_project_boq_codes_and_boq_headers.sql"
echo "wrote supabase/migrations/20260809120000_add_project_boq_codes_and_boq_headers.sql"

echo ""
echo "=== verifying ==="
grep -q "project_code" src/types.ts && echo "OK: project_code in types.ts" || echo "FAIL: project_code missing"
grep -q "BOQHeader" src/types.ts && echo "OK: BOQHeader in types.ts" || echo "FAIL: BOQHeader missing"
test -f src/utils/lookups.ts && echo "OK: lookups.ts created" || echo "FAIL: lookups.ts missing"
grep -q "loadBOQHeaders" src/App.tsx && echo "OK: App.tsx wired" || echo "FAIL: App.tsx not wired"
test -f supabase/migrations/20260809120000_add_project_boq_codes_and_boq_headers.sql && echo "OK: migration file created" || echo "FAIL: migration missing"
